using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
using Raylib_cs;

// Visualization layer for the backend simulation defined in main.cs.
// Generated by claude.ai.

public class SimulationVisualizer
{
    private readonly main _backend;

    // --- Playback ---
    private float _timer = 0f;
    private float _secondsPerTick = 0.6f;
    private bool _paused = false;

    // Grid-space (not pixel) positions used to smoothly interpolate truck movement
    // between backend ticks, keyed by Truck.Id.
    private readonly Dictionary<int, Vector2> _truckRenderFrom = new();
    private readonly Dictionary<int, Vector2> _truckRenderTo = new();

    // --- Layout ---
    private const float Pad = 12f;
    private const float TopBarHeight = 64f;
    private const float SidebarWidth = 300f;
    private const float TruckCardHeight = 108f;

    // --- Palette (dark, portfolio-friendly) ---
    private static readonly Color ColBg          = new Color(24, 24, 37, 255);
    private static readonly Color ColPanel       = new Color(30, 30, 46, 255);
    private static readonly Color ColPanelBorder = new Color(69, 71, 90, 255);
    private static readonly Color ColGridLine    = new Color(49, 50, 68, 255);
    private static readonly Color ColTerrainOpen = new Color(41, 42, 58, 255);
    private static readonly Color ColTerrainSlow = new Color(250, 179, 135, 255);
    private static readonly Color ColWall        = new Color(88, 39, 55, 255);
    private static readonly Color ColDepot       = new Color(166, 227, 161, 255);
    private static readonly Color ColOrder       = new Color(249, 226, 175, 255);
    private static readonly Color ColOrderQueued = new Color(127, 132, 156, 255);
    private static readonly Color ColText        = new Color(205, 214, 244, 255);
    private static readonly Color ColSubtext     = new Color(166, 173, 200, 255);
    private static readonly Color ColGood        = new Color(166, 227, 161, 255);
    private static readonly Color ColWarn        = new Color(249, 226, 175, 255);
    private static readonly Color ColBad         = new Color(243, 139, 168, 255);
    private static readonly Color ColCargoBar    = new Color(137, 180, 250, 255);

    private readonly Color[] _truckColors =
    {
        new Color(137, 180, 250, 255), // blue
        new Color(203, 166, 247, 255), // mauve
        new Color(148, 226, 213, 255), // teal
        new Color(137, 220, 235, 255), // sky
        new Color(245, 194, 231, 255), // pink
        new Color(250, 179, 135, 255), // peach
    };

    public SimulationVisualizer(main backend)
    {
        _backend = backend;
    }

    public void Run()
    {
        Raylib.SetConfigFlags(ConfigFlags.ResizableWindow | ConfigFlags.Msaa4xHint);
        Raylib.InitWindow(1200, 800, "Logistics Dispatch - A* Pathfinding + Clarke-Wright Savings");
        Raylib.SetWindowMinSize(780, 560);
        Raylib.SetTargetFPS(60);

        InitTruckRenderState();

        while (!Raylib.WindowShouldClose())
        {
            HandleInput();
            UpdateLogic();
            Draw();
        }

        Raylib.CloseWindow();
    }

    private void InitTruckRenderState()
    {
        foreach (var truck in _backend.Trucks)
        {
            var pos = new Vector2(truck.CurrentX, truck.CurrentY);
            _truckRenderFrom[truck.Id] = pos;
            _truckRenderTo[truck.Id] = pos;
        }
    }

    private void HandleInput()
    {
        if (Raylib.IsKeyPressed(KeyboardKey.Up)) _secondsPerTick = Math.Max(0.05f, _secondsPerTick - 0.1f);
        if (Raylib.IsKeyPressed(KeyboardKey.Down)) _secondsPerTick = Math.Min(2.0f, _secondsPerTick + 0.1f);
        if (Raylib.IsKeyPressed(KeyboardKey.Space)) _paused = !_paused;
    }

    private void UpdateLogic()
    {
        if (_paused) return;

        _timer += Raylib.GetFrameTime();

        if (_timer >= _secondsPerTick)
        {
            _timer = 0f;

            // Snapshot positions before the backend advances, so we can smoothly
            // interpolate the on-screen trucks toward wherever they end up.
            foreach (var truck in _backend.Trucks)
                _truckRenderFrom[truck.Id] = new Vector2(truck.CurrentX, truck.CurrentY);

            _backend.TickSimulation();

            foreach (var truck in _backend.Trucks)
                _truckRenderTo[truck.Id] = new Vector2(truck.CurrentX, truck.CurrentY);
        }
    }

    private void Draw()
    {
        Raylib.BeginDrawing();
        Raylib.ClearBackground(ColBg);

        int screenWidth = Raylib.GetScreenWidth();
        int screenHeight = Raylib.GetScreenHeight();

        float sidebarWidth = Math.Min(SidebarWidth, screenWidth * 0.35f);
        var topBar = new Rectangle(0, 0, screenWidth, TopBarHeight);
        var gridArea = new Rectangle(
            Pad, TopBarHeight + Pad,
            screenWidth - sidebarWidth - Pad * 3,
            screenHeight - TopBarHeight - Pad * 2);
        var sidebarArea = new Rectangle(
            screenWidth - sidebarWidth - Pad, TopBarHeight + Pad,
            sidebarWidth, screenHeight - TopBarHeight - Pad * 2);

        DrawTopBar(topBar);
        DrawGrid(gridArea);
        DrawRoutesAndOrders(gridArea);
        DrawTrucks(gridArea);
        DrawSidebar(sidebarArea);

        if (_backend.IsSimulationFinished)
            DrawCompletionOverlay(new Rectangle(0, 0, screenWidth, screenHeight));

        Raylib.EndDrawing();
    }

    // ---------------------------------------------------------------- top bar ----

    private void DrawTopBar(Rectangle area)
    {
        Raylib.DrawRectangleRec(area, ColPanel);
        Raylib.DrawLineEx(new Vector2(area.X, area.Y + area.Height), new Vector2(area.X + area.Width, area.Y + area.Height), 2f, ColPanelBorder);

        Raylib.DrawText("LOGISTICS DISPATCH", (int)Pad, 12, 22, ColText);
        Raylib.DrawText("A* pathfinding + Clarke-Wright route savings", (int)Pad, 36, 12, ColSubtext);

        string tickLabel = $"Tick {_backend.CurrentTick}";
        int tickW = Raylib.MeasureText(tickLabel, 20);
        Raylib.DrawText(tickLabel, (int)(area.Width - tickW - Pad), 12, 20, ColText);

        string statusLabel = _paused ? "PAUSED" : $"{1f / _secondsPerTick:F1} ticks/sec";
        int statusW = Raylib.MeasureText(statusLabel, 12);
        Raylib.DrawText(statusLabel, (int)(area.Width - statusW - Pad), 36, 12, _paused ? ColBad : ColSubtext);

        string hint = "SPACE pause   |   UP/DOWN speed";
        int hintW = Raylib.MeasureText(hint, 11);
        Raylib.DrawText(hint, (int)(area.Width / 2f - hintW / 2f), 24, 11, ColSubtext);
    }

    // ------------------------------------------------------------------- grid ----

    private (float cellW, float cellH) GetCellSize(Rectangle area)
    {
        int cols = _backend.testingGrid.GetLength(1);
        int rows = _backend.testingGrid.GetLength(0);
        return (area.Width / cols, area.Height / rows);
    }

    private Vector2 GridToScreen(Rectangle area, float gx, float gy)
    {
        var (cw, ch) = GetCellSize(area);
        return new Vector2(area.X + gx * cw, area.Y + gy * ch);
    }

    private void DrawGrid(Rectangle area)
    {
        int rows = _backend.testingGrid.GetLength(0);
        int cols = _backend.testingGrid.GetLength(1);
        var (cw, ch) = GetCellSize(area);

        for (int y = 0; y < rows; y++)
        {
            for (int x = 0; x < cols; x++)
            {
                int cost = _backend.testingGrid[y, x];
                Color cell = cost == 99 ? ColWall : cost >= 5 ? ColTerrainSlow : ColTerrainOpen;

                float px = area.X + x * cw;
                float py = area.Y + y * ch;
                Raylib.DrawRectangleRec(new Rectangle(px, py, cw, ch), cell);
                Raylib.DrawRectangleLinesEx(new Rectangle(px, py, cw, ch), 1f, ColGridLine);
            }
        }

        Raylib.DrawRectangleLinesEx(area, 2f, ColPanelBorder);
    }

    // ------------------------------------------------------ routes and orders ----

    private void DrawRoutesAndOrders(Rectangle area)
    {
        var (cw, ch) = GetCellSize(area);
        float minCell = Math.Min(cw, ch);

        // Depot
        if (_backend.CentralDepot != null)
        {
            var center = GridToScreen(area, _backend.CentralDepot.X + 0.5f, _backend.CentralDepot.Y + 0.5f);
            var rect = new Rectangle(center.X - minCell * 0.35f, center.Y - minCell * 0.35f, minCell * 0.7f, minCell * 0.7f);
            Raylib.DrawRectangleRounded(rect, 0.3f, 6, ColDepot);
            Raylib.DrawRectangleLinesEx(rect, 2f, ColBg);

            string label = "DEPOT";
            int fontSize = Math.Max(8, (int)(minCell * 0.14f));
            int textW = Raylib.MeasureText(label, fontSize);
            Raylib.DrawText(label, (int)(center.X - textW / 2f), (int)(center.Y + minCell * 0.4f), fontSize, ColText);
        }

        // Per-truck planned route (faint straight lines) + actual A* path (solid, bends around terrain)
        for (int i = 0; i < _backend.Trucks.Count; i++)
        {
            var truck = _backend.Trucks[i];
            Color truckColor = _truckColors[i % _truckColors.Length];
            Vector2 renderPos = GetTruckRenderGridPos(truck);

            if (truck.AssignedRoute.Count > 0 && _backend.CentralDepot != null)
            {
                Vector2 prev = renderPos;
                foreach (var stop in truck.AssignedRoute)
                {
                    Vector2 next = new Vector2(stop.X, stop.Y);
                    DrawGridLine(area, prev, next, Raylib.Fade(truckColor, 0.25f), 2f);
                    prev = next;
                }
                DrawGridLine(area, prev, new Vector2(_backend.CentralDepot.X, _backend.CentralDepot.Y), Raylib.Fade(truckColor, 0.25f), 2f);
            }

            var physicalPath = truck.CurrentPhysicalPath.ToArray();
            for (int p = 0; p < physicalPath.Length - 1; p++)
            {
                Vector2 a = new Vector2(physicalPath[p].X, physicalPath[p].Y);
                Vector2 b = new Vector2(physicalPath[p + 1].X, physicalPath[p + 1].Y);
                DrawGridLine(area, a, b, truckColor, 3f);
            }
        }

        // Orders already assigned to a truck but not yet delivered - dim, ringed in the truck's color
        for (int i = 0; i < _backend.Trucks.Count; i++)
        {
            var truck = _backend.Trucks[i];
            Color truckColor = _truckColors[i % _truckColors.Length];
            foreach (var order in truck.PendingOrders.ToArray())
                DrawOrderMarker(area, order, ColOrderQueued, truckColor, false);
        }

        // Orders still waiting for a truck - bright, gently pulsing
        foreach (var order in _backend.UnassignedOrders)
            DrawOrderMarker(area, order, ColOrder, ColBg, true);
    }

    private void DrawGridLine(Rectangle area, Vector2 gridA, Vector2 gridB, Color color, float thickness)
    {
        Vector2 a = GridToScreen(area, gridA.X + 0.5f, gridA.Y + 0.5f);
        Vector2 b = GridToScreen(area, gridB.X + 0.5f, gridB.Y + 0.5f);
        Raylib.DrawLineEx(a, b, thickness, color);
    }

    private void DrawOrderMarker(Rectangle area, Order order, Color fill, Color ringColor, bool pulse)
    {
        var (cw, ch) = GetCellSize(area);
        float minCell = Math.Min(cw, ch);
        Vector2 center = GridToScreen(area, order.X + 0.5f, order.Y + 0.5f);

        float radius = minCell * 0.22f + minCell * 0.12f * Math.Clamp(order.StorageRequired / 30f, 0f, 1f);
        if (pulse)
            radius += (float)(Math.Sin(Raylib.GetTime() * 3.0) * minCell * 0.02f);

        Raylib.DrawCircleV(center, radius, fill);
        Raylib.DrawCircleLines((int)center.X, (int)center.Y, radius, ringColor);

        string label = order.StorageRequired.ToString();
        int fontSize = Math.Max(8, (int)(minCell * 0.16f));
        int textW = Raylib.MeasureText(label, fontSize);
        Raylib.DrawText(label, (int)(center.X - textW / 2f), (int)(center.Y - fontSize / 2f), fontSize, ColBg);
    }

    // ----------------------------------------------------------------- trucks ----

    private Vector2 GetTruckRenderGridPos(Truck truck)
    {
        Vector2 from = _truckRenderFrom.TryGetValue(truck.Id, out var f) ? f : new Vector2(truck.CurrentX, truck.CurrentY);
        Vector2 to = _truckRenderTo.TryGetValue(truck.Id, out var t) ? t : new Vector2(truck.CurrentX, truck.CurrentY);
        float progress = _paused ? 1f : Math.Clamp(_timer / _secondsPerTick, 0f, 1f);
        return LerpVec(from, to, progress);
    }

    private static Vector2 LerpVec(Vector2 a, Vector2 b, float t) => new Vector2(a.X + (b.X - a.X) * t, a.Y + (b.Y - a.Y) * t);

    private void DrawTrucks(Rectangle area)
    {
        var (cw, ch) = GetCellSize(area);
        float minCell = Math.Min(cw, ch);
        float size = minCell * 0.5f;

        for (int i = 0; i < _backend.Trucks.Count; i++)
        {
            var truck = _backend.Trucks[i];
            Color color = _truckColors[i % _truckColors.Length];
            Vector2 gridPos = GetTruckRenderGridPos(truck);
            Vector2 center = GridToScreen(area, gridPos.X + 0.5f, gridPos.Y + 0.5f);

            var body = new Rectangle(center.X - size / 2f, center.Y - size / 2f, size, size);
            Raylib.DrawRectangleRounded(body, 0.35f, 8, color);
            Raylib.DrawRectangleLinesEx(body, 2f, ColBg);

            string label = $"T{truck.Id}";
            int fontSize = Math.Max(9, (int)(minCell * 0.16f));
            int textW = Raylib.MeasureText(label, fontSize);
            Raylib.DrawText(label, (int)(center.X - textW / 2f), (int)(center.Y - fontSize / 2f), fontSize, ColBg);

            // State pill above the truck
            string stateLabel = truck.State.ToString();
            int stateFontSize = Math.Max(8, (int)(minCell * 0.12f));
            int stateW = Raylib.MeasureText(stateLabel, stateFontSize);
            float pillY = center.Y - size / 2f - stateFontSize - 6f;
            var pillRect = new Rectangle(center.X - stateW / 2f - 4f, pillY, stateW + 8f, stateFontSize + 4f);
            Raylib.DrawRectangleRounded(pillRect, 0.5f, 6, Raylib.Fade(ColPanel, 0.9f));
            Raylib.DrawText(stateLabel, (int)(center.X - stateW / 2f), (int)pillY + 2, stateFontSize, StateColor(truck.State));
        }
    }

    private Color StateColor(TruckState state) => state switch
    {
        TruckState.Driving => ColGood,
        TruckState.Loading => ColWarn,
        TruckState.Refueling => new Color(137, 220, 235, 255),
        _ => ColSubtext,
    };

    // ---------------------------------------------------------------- sidebar ----

    private void DrawSidebar(Rectangle area)
    {
        Raylib.DrawRectangleRounded(area, 0.03f, 6, ColPanel);
        Raylib.DrawRectangleLinesEx(area, 1.5f, ColPanelBorder);

        Raylib.BeginScissorMode((int)area.X, (int)area.Y, (int)area.Width, (int)area.Height);

        float x = area.X + Pad;
        float width = area.Width - Pad * 2;
        float y = area.Y + Pad;

        Raylib.DrawText("FLEET STATUS", (int)x, (int)y, 16, ColText);
        y += 26;

        for (int i = 0; i < _backend.Trucks.Count; i++)
        {
            var truck = _backend.Trucks[i];
            Color color = _truckColors[i % _truckColors.Length];
            var cardRect = new Rectangle(x, y, width, TruckCardHeight);
            Raylib.DrawRectangleRounded(cardRect, 0.12f, 6, ColBg);
            Raylib.DrawRectangleLinesEx(cardRect, 1f, ColPanelBorder);

            Raylib.DrawRectangleRounded(new Rectangle(x + 8, y + 8, 14, 14), 0.4f, 4, color);
            Raylib.DrawText($"Truck {truck.Id}", (int)(x + 28), (int)(y + 6), 14, ColText);

            string stateLabel = truck.State.ToString();
            int stateW = Raylib.MeasureText(stateLabel, 12);
            Raylib.DrawText(stateLabel, (int)(x + width - stateW - 8), (int)(y + 8), 12, StateColor(truck.State));

            DrawStatBar(x + 8, y + 32, width - 16, "Fuel", truck.FuelCapacity, truck.MaxFuelCapacity, FuelColor(truck.FuelCapacity, truck.MaxFuelCapacity));
            DrawStatBar(x + 8, y + 58, width - 16, "Cargo", truck.CurrentStorage, truck.MaxStorage, ColCargoBar);

            string routeText = truck.AssignedRoute.Count > 0
                ? string.Join(" -> ", truck.AssignedRoute.Select(o => $"O{o.Id}"))
                : "(no route)";
            Raylib.DrawText(Truncate(routeText, width - 16, 11), (int)(x + 8), (int)(y + 86), 11, ColSubtext);

            y += TruckCardHeight + 10;
        }

        // Orders progress
        y += 6;
        Raylib.DrawText("ORDERS", (int)x, (int)y, 16, ColText);
        y += 26;

        int totalOrders = _backend.Orders.Count;
        int inTransit = _backend.Trucks.Sum(t => t.PendingOrders.Count);
        int unassigned = _backend.UnassignedOrders.Count;
        int delivered = Math.Max(0, totalOrders - unassigned - inTransit);

        DrawStatBar(x, y, width, "Delivered", delivered, totalOrders, ColGood);
        y += 24;
        Raylib.DrawText($"{unassigned} unassigned   |   {inTransit} in transit", (int)x, (int)y, 11, ColSubtext);
        y += 28;

        // Legend
        Raylib.DrawText("LEGEND", (int)x, (int)y, 16, ColText);
        y += 24;
        y = DrawLegendRow(x, y, ColTerrainOpen, "Open terrain (cost 1)");
        y = DrawLegendRow(x, y, ColTerrainSlow, "Slow terrain (cost 5)");
        y = DrawLegendRow(x, y, ColWall, "Wall (blocked)");
        y = DrawLegendRow(x, y, ColDepot, "Depot");
        y = DrawLegendRow(x, y, ColOrder, "Unassigned order");
        y = DrawLegendRow(x, y, ColOrderQueued, "Order in transit");

        Raylib.EndScissorMode();
    }

    private void DrawStatBar(float x, float y, float width, string label, int current, int max, Color fillColor)
    {
        string caption = $"{label}  {current}/{max}";
        Raylib.DrawText(caption, (int)x, (int)y, 10, ColSubtext);

        float barY = y + 13;
        float barHeight = 8f;
        float pct = max > 0 ? Math.Clamp(current / (float)max, 0f, 1f) : 0f;

        Raylib.DrawRectangleRounded(new Rectangle(x, barY, width, barHeight), 0.5f, 4, ColGridLine);
        if (pct > 0f)
            Raylib.DrawRectangleRounded(new Rectangle(x, barY, width * pct, barHeight), 0.5f, 4, fillColor);
    }

    private Color FuelColor(int current, int max)
    {
        float pct = max > 0 ? current / (float)max : 0f;
        if (pct > 0.5f) return ColGood;
        if (pct > 0.2f) return ColWarn;
        return ColBad;
    }

    private float DrawLegendRow(float x, float y, Color swatch, string label)
    {
        Raylib.DrawRectangleRounded(new Rectangle(x, y, 14, 14), 0.3f, 4, swatch);
        Raylib.DrawText(label, (int)(x + 20), (int)y, 11, ColSubtext);
        return y + 20;
    }

    private string Truncate(string text, float maxWidth, int fontSize)
    {
        if (Raylib.MeasureText(text, fontSize) <= maxWidth) return text;
        const string ellipsis = "...";
        while (text.Length > 0 && Raylib.MeasureText(text + ellipsis, fontSize) > maxWidth)
            text = text.Substring(0, text.Length - 1);
        return text + ellipsis;
    }

    // -------------------------------------------------------------- completion ----

    private void DrawCompletionOverlay(Rectangle screen)
    {
        Raylib.DrawRectangleRec(screen, Raylib.Fade(Color.Black, 0.55f));

        float panelW = 440f;
        float panelH = 160f;
        var panel = new Rectangle(screen.Width / 2f - panelW / 2f, screen.Height / 2f - panelH / 2f, panelW, panelH);
        Raylib.DrawRectangleRounded(panel, 0.12f, 8, ColPanel);
        Raylib.DrawRectangleLinesEx(panel, 2f, ColGood);

        string title = "SHIFT COMPLETE";
        int titleW = Raylib.MeasureText(title, 26);
        Raylib.DrawText(title, (int)(panel.X + panel.Width / 2f - titleW / 2f), (int)(panel.Y + 24), 26, ColGood);

        string sub = $"All {_backend.Orders.Count} orders delivered in {_backend.CurrentTick} ticks";
        int subW = Raylib.MeasureText(sub, 14);
        Raylib.DrawText(sub, (int)(panel.X + panel.Width / 2f - subW / 2f), (int)(panel.Y + 66), 14, ColText);

        string fleet = $"{_backend.Trucks.Count} trucks dispatched";
        int fleetW = Raylib.MeasureText(fleet, 12);
        Raylib.DrawText(fleet, (int)(panel.X + panel.Width / 2f - fleetW / 2f), (int)(panel.Y + 96), 12, ColSubtext);
    }
}